Account original = new Account(Id = '001B000001DVM9tIAH', Name = 'Acme');
List<Account> accounts = new List<Account>{original};
List<Account> cloned = accounts.deepClone(true);
Account clonedAccount = cloned.get(0);
clonedAccount.Name = 'Clone';
System.assertEquals('Acme', accounts.get(0).Name);
System.assertEquals('Clone', cloned.get(0).Name);
System.assertEquals(original.Id, cloned.get(0).Id);

